            "content": "في فضل الوضوء:\nالحمد لله رب العالمين، والصلاة والسلام على نبينا محمد، وعلى آله وصحبه أجمعين. أما بعد:\nفإن الوضوء من أجلِّ العبادات وأعظم شعائر الإسلام، وهو مفتاح الصلاة، وسبب لمغفرة الذنوب، ورفعة الدرجات، ودخول الجنة، وعلامة لأمة محمد ﷺ يوم القيامة. وقد وردت في فضله نصوص كثيرة من القرآن الكريم والسنة النبوية الصحيحة، وفيما يأتي جمعٌ لأهم تلك النصوص مرتبة بحسب موضوعاتها.",
