            "content": "أولًا: فضل الوضوء في القرآن الكريم\n\n1- محبة الله للمتطهرين:\nقال تعالى: ﴿إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ﴾ [البقرة: 222].\nفالطهارة سبب لمحبة الله تعالى، وأعظم الطهارة طهارة القلب والتوبة، ومن تمامها الطهارة الحسية التي يدخل فيها الوضوء.\n\n2- الأمر بالوضوء:\nقال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ...﴾ [المائدة: 6].\nوهذه أعظم آية في بيان فرضية الوضوء وصفته.",
