                        "content": "المطلب الثاني: المؤذنون أطول الناس أعناقًا يوم القيامة\nعن معاوية رضي الله عنه قال: قال رسول الله ﷺ:\n«المؤذنون أطول الناس أعناقًا يوم القيامة.»\nرواه مسلم (387).",
