                        "id": "adhan-hadith-3",
                        "content": "المطلب الثالث: شهادة جميع المخلوقات للمؤذن\nعن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:\n«لا يسمع مدى صوت المؤذن جن ولا إنس ولا شيء إلا شهد له يوم القيامة.»\nرواه البخاري (609).\nوفي رواية النسائي: «من حجر ولا شجر ولا مدر.»\nالفوائد:\n- عموم شهادة المخلوقات للمؤذن.\n- استمرار ثواب المؤذن بعد انتهاء الأذان.",
