                        "id": "adhan-hadith-4",
                        "content": "المطلب الرابع: مغفرة الذنوب للمؤذن\nعن البراء بن عازب رضي الله عنه قال: قال رسول الله ﷺ:\n«إن الله وملائكته يصلون على الصف الأول، والمؤذن يغفر له مدى صوته، ويصدقه من سمعه من رطب ويابس، وله مثل أجر من صلى معه.»\nرواه أحمد والنسائي، وصححه الألباني.\nالفوائد:\n- مغفرة الذنوب للمؤذن.\n- شهادة المخلوقات له.\n- حصوله على أجور المصلين معه.",
