                        "id": "adhan-hadith-5",
                        "content": "المطلب الخامس: لو يعلم الناس ما في النداء لاستهموا عليه\nعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:\n«لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا.»\nمتفق عليه.\nقال ابن حجر:\nفيه أعظم دليل على كثرة ثواب الأذان.",
