                        "content": "المطلب السادس: إجابة الدعاء بين الأذان والإقامة\nعن أنس بن مالك رضي الله عنه قال: قال رسول الله ﷺ:\n«الدعاء لا يرد بين الأذان والإقامة.»\nرواه أبو داود والترمذي، وصححه الألباني.\nالفوائد:\n- استحباب الإكثار من الدعاء بين الأذان والإقامة.\n- أن هذا الوقت من أوقات إجابة الدعاء.",
