                        "id": "adhan-hadith-9",
                        "content": "المطلب التاسع: الأمر بإجابة المؤذن\nعن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:\n«إذا سمعتم النداء فقولوا مثل ما يقول المؤذن.»\nمتفق عليه.\nووجه الدلالة أن الشارع رتب على متابعة المؤذن الفضائل العظيمة، مما يدل على مكانة الأذان وعظيم شأنه.",
