                        "content": "المطلب العاشر: المؤذن مؤتمن\nعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:\n«الإمام ضامن، والمؤذن مؤتمن، اللهم أرشد الأئمة، واغفر للمؤذنين.»\nرواه أبو داود والترمذي، وصححه الألباني.\nوجه الدلالة:\nأن النبي ﷺ خص المؤذنين بالدعاء بالمغفرة، ووصفهم بالأمانة؛ لما تحملوه من مسؤولية إعلام الناس بدخول أوقات العبادة.",
