                        "content": "خامسًا: الصلوات الخمس تنهى عن الفحشاء والمنكر\nقال الله تعالى:\n﴿وَأَقِمِ الصَّلَاةَ ۖ إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ﴾ [العنكبوت: 45].",
