                        "id": "fp-7",
                        "content": "سابعًا: المحافظة على الصلوات الخمس سبب لدخول الجنة\nعن أبي أمامة رضي الله عنه قال: سمعت رسول الله ﷺ يخطب في حجة الوداع فقال:\n«اتقوا الله ربكم، وصلوا خمسكم، وصوموا شهركم، وأدوا زكاة أموالكم، وأطيعوا ذا أمركم، تدخلوا جنة ربكم.»",
