                        "id": "fp-8",
                        "content": "ثامنًا: الصلوات الخمس تمحو الخطايا كما يغسل النهر الدرن\nعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:\n«أرأيتم لو أن نهرًا بباب أحدكم يغتسل فيه كل يوم خمس مرات، هل يبقى من درنه شيء؟»\nقالوا: لا يبقى من درنه شيء.\nقال:\n«فذلك مثل الصلوات الخمس، يمحو الله بهن الخطايا.»",
