            "content": "المبحث الثاني: الأحاديث الصحيحة في فضل طلب العلم وسلوك طريقه\n1- سلوك طريق العلم طريقٌ إلى الجنة:\nعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال: «وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا، سَهَّلَ اللهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ».",
