            "content": "المبحث الثاني: الأحاديث الصحيحة في فضل طلب العلم وسلوك طريقه\n5- فضل شهود مجالس العلم وتذاكره:\nعن أبي واقد الليثي رضي الله عنه أن رسول الله ﷺ بينما هو جالس في المسجد والناس معه إذ أقبل ثلاثة نفر... فأما أحدهم فرأى فرجة في الحلقة فجلس فيها، وأما الآخر فجلس خلفهم، وأما الثالث فأدبر ذاهباً، فلما فرغ رسول الله ﷺ قال: «أَلاَ أُخْبِرُكُمْ عَنِ النَّفَرِ الثَّلاَثَةِ؟ أَمَّا أَحَدُهُمْ فَأَوَى إِلَى اللَّهِ فَآوَاهُ اللَّهُ، وَأَمَّا الآخَرُ فَاسْتَحْيَا فَاسْتَحْيَا اللَّهُ مِنْهُ، وَأَمَّا الآخَرُ فَأَعْرَضَ فَأَعْرَضَ اللَّهُ عَنْهُ».",
