            "content": "المبحث الثالث: الأحاديث الصحيحة في فضل العلماء ومكانتهم ونشرهم للعلم\n1- العلماء هم ورثة الأنبياء:\nعن أبي الدرداء رضي الله عنه عن النبي ﷺ قال: «...وَإِنَّ الْعُلَمَاءَ وَرَثَةُ الْأَنْبِيَاءِ، وَإِنَّ الْأَنْبِيَاءَ لَمْ يُوَرِّثُوا دِينَارًا وَلَا دِرْهَمًا، وَإِنَّمَا وَرَّثُوا الْعِلْمَ، فَمَنْ أَخَذَهُ أَخَذَ بِحَظٍّ وَافِرٍ».",
