            "content": "المبحث الثالث: الأحاديث الصحيحة في فضل العلماء ومكانتهم ونشرهم للعلم\n2- فضل العالم على العابد وصلوات المخلوقات على معلم الخير:\nعن أبي أمامة الباهلي رضي الله عنه قال: ذُكِرَ لِرَسُولِ اللَّهِ ﷺ رَجُلاَنِ؛ أَحَدُهُمَا عَابِدٌ وَالأَخَرُ عَالِمٌ، فَقَالَ رَسُولُ اللَّهِ ﷺ: «فَضْلُ العَالِمِ عَلَى العَابِدِ كَفَضْلِي عَلَى أَدْنَاكُمْ»، ثُمَّ قَالَ رَسُولُ اللَّهِ ﷺ: «إِنَّ اللَّهَ وَمَلَائِكَتَهُ وَأَهْلَ السَّمَوَاتِ وَالأَرَضِينَ حَتَّى النَّمْلَةَ فِي جُحْرِهَا وَحَتَّى الحُوتَ لَيُصَلُّونَ عَلَى مُعَلِّمِ النَّاسِ الخَيْرَ».",
