                                "id": "q2-2",
                                "content": "2- لقارئ القرآن بكل حرف حسنة مضاعفة\nعن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله ﷺ:\n«مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللهِ فَلَهُ بِهِ حَسَنَةٌ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا، لا أَقُولُ: الم حَرْفٌ، وَلَكِنْ أَلِفٌ حَرْفٌ، وَلَامٌ حَرْفٌ، وَمِيمٌ حَرْفٌ».",
