                                "id": "q2-3",
                                "content": "3- الماهر بالقرآن ومن يشق عليه لهما أجر عظيم\nعن عائشة رضي الله عنها قالت: قال رسول الله ﷺ:\n«الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ».",
                                "source": "رواه البخاري ومسلم",
