                                "content": "1- تدبر القرآن هو المقصود من إنزاله\nقال الله تعالى:\n﴿كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ﴾ [ص: 29].",
