                                "content": "2- القرآن يهدي إلى أقوم الأعمال والأحوال\nقال الله تعالى:\n﴿إِنَّ هَٰذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ﴾ [الإسراء: 9].",
