                                "content": "3- أهل القرآن المنتفعون به هم أهل الخشية والإنابة\nقال الله تعالى:\n﴿لَوْ أَنْزَلْنَا هَٰذَا الْقُرْآنَ عَلَىٰ جَبَلٍ لَرَأَيْتَهُ خَاشِعًا مُتَصَدِّعًا مِنْ خَشْيَةِ اللَّهِ﴾ [الحشر: 21].",
