                                "content": "1- خير الناس من تعلم القرآن وعلمه\nعن عثمان بن عفان رضي الله عنه قال: قال رسول الله ﷺ:\n«خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ».",
