                                "content": "2- أهل القرآن هم أهل الله وخاصته\nعن أنس بن مالك رضي الله عنه قال: قال رسول الله ﷺ:\n«إِنَّ لِلَّهِ أَهْلِينَ مِنَ النَّاسِ».\nقالوا: يا رسول الله، من هم؟ قال:\n«هُمْ أَهْلُ الْقُرْآنِ، أَهْلُ اللَّهِ وَخَاصَّتُهُ».",
