            "id": "time-15",
            "content": "3. أيام البيض (13 و14 و15 من كل شهر هجري)\nصيامها كصيام الدهر: عن جرير بن عبد الله رضي الله عنه عن النبي ﷺ قال: «صِيَامُ ثَلاَثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ صِيَامُ الدَّهْرِ، وَأَيَّامُ الْبِيضِ صَبَاحَ ثَلاَثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ». (رواه النسائي، وصححه الألباني).",
