            "content": "فضائل الأماكن والبقاع:\n\nالحمد لله الذي خلق الأمكنة والبقاع، وفضّل بعضها على بعض حكمةً منه وعدلاً، وجعل فيها معالم لهديه ومناسك لعبادته، والصلاة والسلام على نبينا محمد المصطفى الذي أُسرِيَ به من المسجد الحرام إلى المسجد الأقصى، وعلى آله وصحبه أجمعين.\nأما بعد؛ فإن من مظاهر تكريم الله تعالى لبعض بقاع الأرض أن جعل لها حرمةً وفضلاً، وكاتَبَ لأهلها والمصلين فيها أجوراً مضاعفة، وجعل زيارتها أو السكنى فيها سبباً لتنزل الرحمات ومنها :",
