            "content": "المبحث الأول: فضل مكة المكرمة والحرم المكي\nتُعد مكة المكرمة أحب البقاع إلى الله تعالى، وفيها أول بيت وُضع للناس، وتضاعف فيها الحسنات:\n\n1. أول بيت وُضع للناس ومقام إبراهيم:\nمن القرآن الكريم: قال تعالى: {إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَالَمِينَ * فِيهِ آيَاتٌ بَيِّنَاتٌ مَّقَامُ إِبْرَاهِيمَ ۖ وَمَن دَخَلَهُ كَانَ آمِنًا} [آل عمران: 96-97].",
