            "content": "3. أحب البلاد إلى الله وإلى رسوله ﷺ:\nمن السنة النبوية: عن عبد الله بن عدي بن حمراء رضي الله عنه قال: رأيت رسول الله ﷺ واقفاً على الحَزْوَرَةِ (موضع بمكة) فقال: «وَاللَّهِ إِنَّكِ لَخَيْرُ أَرْضِ اللَّهِ، وَأَحَبُّ أَرْضِ اللَّهِ إِلَى اللَّهِ، وَلَوْلاَ أَنِّي أُخْرِجْتُ مِنْكِ مَا خَرَجْتُ». (رواه الترمذي وابن ماجه، وصححه الألباني).",
