            "content": "4. مضاعفة الصلاة في المسجد الحرام:\nمن السنة النبوية: عن جابر بن عبد الله رضي الله عنهما أن رسول الله ﷺ قال: «صَلاَةٌ فِي مَسْجِدِي هَذَا أَفْضَلُ مِنْ أَلْفِ صَلاَةٍ فِيمَا سِوَاهُ إِلاَّ المَسْجِدَ الحَرَامَ، وَصَلاَةٌ فِي المَسْجِدِ الحَرَامِ أَفْضَلُ مِنْ مِائَةِ أَلْفِ صَلاَةٍ فِيمَا سِوَاهُ». (رواه أحمد وابن ماجه، وصححه الألباني).",
