            "content": "المبحث الثاني: فضل المدينة المنورة والحرم النبوي\nالمدينة المنورة هي دار الهجرة والإيمان، وتحفّها البركة وحرمها النبي ﷺ كما حُرّمت مكة:\n\n1. المدينة دار الإيمان ومأرزه:\nمن السنة النبوية: عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال: «إِنَّ الإِيمَانَ لَيَأْرِزُ إِلَى المَدِينَةِ كَمَا تَأْرِزُ الحَيَّةُ إِلَى جُحْرِهَا». (رواه البخاري ومسلم).",
