            "id": "places-8",
            "content": "3. تحريم المدينة وحمايتها من الطاعون والدجال:\nمن السنة النبوية: عن علي بن أبي طالب رضي الله عنه عن النبي ﷺ قال: «المَدِينَةُ حَرَمٌ مَا بَيْنَ عَيْرٍ إِلَى ثَوْرٍ...». (رواه البخاري ومسلم).\nوعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ: «عَلَى أَنْقَابِ المَدِينَةِ مَلاَئِكَةٌ، لاَ يدْخُلُهَا الطَّاعُونُ وَلاَ الدَّجَّالُ». (رواه البخاري ومسلم).",
