            "id": "places-9",
            "content": "4. فضل الروضة الشريفة والشفاعة لمن صبر على لأوائها:\nمن السنة النبوية: عن عبد الله بن زيد رضي الله عنه عن النبي ﷺ قال: «مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الجَنَّةِ». (رواه البخاري ومسلم).\nوعن أَبِي سَعِيدٍ الخُدْرِيِّ رضي الله عنه عَنِ النَّبِيِّ ﷺ أَنَّهُ قَالَ: «لاَ يَصْبِرُ عَلَى لأْوَائِهَا وَشِدَّتِهَا أَحَدٌ إِلاَّ كُنْتُ لَهُ شَفِيعًا أَوْ شَهِيدًا يَوْمَ القِيَامَةِ». (رواه مسلم).",
