            "content": "2. الشام خيرة الله من أرضه صفوته من عباده:\nمن السنة النبوية: عن عبد الله بن حوالة رضي الله عنه قال: قال رسول الله ﷺ: «سَيَصِيرُ الأَمْرُ إِلَى أَنْ تَكُونُوا جُنُودًا مُجَنَّدَةً: جُنْدٌ بِالشَّامِ، وَجُنْدٌ بِاليَمَنِ، وَجُنْدٌ بِالعِرَاقِ»، قال ابن حوالة: خِرْ لي يا رسول الله إن أدركتُ ذلك، فقال: «عَلَيْكَ بِالشَّامِ، فَإِنَّهَا خِيَرَةُ اللَّهِ مِنْ أَرْضِهِ، يَجْتَبِي إِلَيْهَا خِيَرَتَهُ مِنْ عِبَادِهِ...». (رواه أبو داود وأحمد، وصححه الألباني).",
