          {
            "id": "prophets-item-4",
            "content": "المبحث الثالث: التفاضل بين الأنبياء والرسل\nمع اتفاق الأنبياء في أصل الفضل، فإن الله سبحانه فضل بعضهم على بعض، بحسب ما اختصهم به من الرسالات، والمعجزات، والدرجات.\nقال تعالى:\n﴿تِلْكَ الرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ ۘ مِّنْهُم مَّن كَلَّمَ اللَّهُ وَرَفَعَ بَعْضَهُمْ دَرَجَاتٍ﴾ [البقرة: 253].\nفذكر سبحانه من صور التفضيل:\n- التكليم، وهو خاص بموسى عليه السلام.\n- رفع الدرجات، ويشمل ما خص الله به بعض رسله من الفضائل.\nوقال تعالى:\n﴿وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَىٰ بَعْضٍ وَآتَيْنَا دَاوُودَ زَبُورًا﴾ [الإسراء: 55].\nوفي الصحيحين من حديث أبي هريرة رضي الله عنه أن النبي ﷺ قال:\n«الأنبياء إخوةٌ لعلات، أمهاتهم شتى، ودينهم واحد.»\nأي أن شرائعهم قد تختلف، أما أصل الدين، وهو توحيد الله، فواحد.\nكما ثبت في الصحيحين قوله ﷺ:\n«ما من الأنبياء نبي إلا أُعطي من الآيات ما مثله آمن عليه البشر، وإنما كان الذي أوتيته وحيًا أوحاه الله إلي، فأرجو أن أكون أكثرهم تابعًا يوم القيامة.»\nفهذا الحديث يدل على اشتراك جميع الأنبياء في تأييد الله لهم بالمعجزات، مع اختصاص النبي ﷺ بالقرآن المعجز الباقي إلى قيام الساعة.",
            "source": "سورة البقرة والإسراء والصحيحين",
            "tags": [
              "التفاضل بين الأنبياء",
              "معجزات الأنبياء",
              "توحيد الله"
            ],
            "createdAt": "2026-07-22T00:00:00Z"
          },
          {
            "id": "prophets-item-5",
            "content": "المبحث الرابع: عصمة الأنبياء وصدقهم وأمانتهم\nمن أعظم وجوه فضل الأنبياء أن الله عصمهم في تبليغ رسالته، فلا يبلغون عن الله إلا الحق، كما عصمهم من الكذب والخيانة في أداء الوحي.\nقال تعالى:\n﴿وَمَا يَنطِقُ عَنِ الْهَوَى * إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى﴾ [النجم: 3-4].\nوقال سبحانه:\n﴿وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ الْمُبِينُ﴾ [النور: 54].\nوقد وصف الله أنبياءه بالصدق في مواضع كثيرة، فقال عن إبراهيم:\n﴿وَاذْكُرْ فِي الْكِتَابِ إِبْرَاهِيمَ ۚ إِنَّهُ كَانَ صِدِّيقًا نَّبِيًّا﴾ [مريم: 41].\nوقال عن إسماعيل:\n﴿إِنَّهُ كَانَ صَادِقَ الْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا﴾ [مريم: 54].\nوقال عن إدريس:\n﴿إِنَّهُ كَانَ صِدِّيقًا نَّبِيًّا﴾ [مريم: 56].\nفالصدق والأمانة أصل جامع لجميع الأنبياء، وهو الذي قامت عليه دعوتهم.",
            "source": "سورة النجم والنور ومريم",
            "tags": [
              "عصمة الأنبياء",
              "الصدق والأمانة",
              "سورة مريم"
            ],
            "createdAt": "2026-07-22T00:00:00Z"
          }
