            "id": "prophets-item-12",
            "content": "الفصل الثالث: فضل بقية الأنبياء والرسل عليهم الصلاة والسلام\nالمبحث الأول: فضل آدم عليه السلام (أبو البشر وأول الأنبياء)\nآدم عليه السلام أول البشر وأول الأنبياء، خلقه الله بيده، وأسكنه جنته، وعلمه ما لم يعلم غيره.\nقال تعالى:\n﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً﴾ [البقرة: 30].\n\nأولًا: خلقه الله وكرمه\nقال تعالى:\n﴿إِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن طِينٍ * فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ﴾ [ص: 71-72].\nفكان سجود الملائكة له سجود تكريم بأمر الله، لا سجود عبادة.\n\nثانيًا: تعليمه الأسماء\nقال تعالى:\n﴿وَعَلَّمَ آدَمَ الْأَسْمَاءَ كُلَّهَا﴾ [البقرة: 31].\nفكان العلم أول تكريم ناله آدم عليه السلام.\n\nثالثًا: مكانته بين الأنبياء\nثبت في الصحيحين في حديث الشفاعة أن الناس يأتون إلى آدم يوم القيامة فيقولون:\n«أنت أبو البشر، خلقك الله بيده، ونفخ فيك من روحه، وأسجد لك ملائكته، وعلمك أسماء كل شيء».\nوهذا يدل على عظيم منزلته.\n\nرابعًا: توبته وقبول الله لها\nلما وقع آدم في المخالفة بادر إلى التوبة.\nقال تعالى:\n﴿فَتَلَقَّىٰ آدَمُ مِن رَّبِّهِ كَلِمَاتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ﴾ [البقرة: 37].\nفكان في قصته تعليم للبشر أن باب التوبة مفتوح.",
