                        {
                                "id": "eth-5-2",
                                "content": "فضل صلة الرحم\nقال الله تعالى:\n﴿وَالَّذِينَ يَصِلُونَ مَا أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ﴾ [الرعد: 21].\nوقال تعالى:\n﴿فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ ۝ أُولَٰئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ﴾ [محمد: 22-23].\n\nوعن أنس بن مالك رضي الله عنه قال: قال رسول الله ﷺ:\n«من أحب أن يُبسط له في رزقه، ويُنسأ له في أثره، فليصل رحمه». [متفق عليه].\n\nوعن أبي أيوب الأنصاري رضي الله عنه أن رجلًا قال: يا رسول الله، أخبرني بعمل يدخلني الجنة. فقال ﷺ:\n«تعبد الله لا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة، وتصل الرحم». [متفق عليه].",
                                "source": "الرعد: 21؛ محمد: 22-23؛ متفق عليه",
                                "tags": [
                                        "صلة الرحم",
                                        "بسط الرزق",
                                        "دخول الجنة"
                                ],
                                "createdAt": "2026-07-25T00:00:00Z"
                        },
                        {
                                "id": "eth-5-3",
                                "content": "فضل حسن الجوار وإكرام الضيف\nقال الله تعالى:\n﴿وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا... وَالْجَارِ ذِي الْقُرْبَىٰ وَالْجَارِ الْجُنُبِ﴾ [النساء: 36].\n\nوعن ابن عمر وعائشة رضي الله عنهم أن رسول الله ﷺ قال:\n«ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه». [متفق عليه].\n\nوعن أبي شريح رضي الله عنه أن النبي ﷺ قال:\n«والله لا يؤمن، والله لا يؤمن، والله لا يؤمن». قيل: من يا رسول الله؟ قال: «الذي لا يأمن جاره بوائقه». [متفق عليه].\n\nوعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:\n«من كان يؤمن بالله واليوم الآخر فليكرم ضيفه». [متفق عليه].",
                                "source": "النساء: 36؛ متفق عليه",
                                "tags": [
                                        "حسن الجوار",
                                        "إكرام الضيف",
                                        "حق الجار"
                                ],
                                "createdAt": "2026-07-25T00:00:00Z"
                        },
                        {
                                "id": "eth-5-4",
                                "content": "فضل إكرام الكبير ورحمة الصغير والإحسان لمن تحت اليد\nقال الله تعالى:\n﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ﴾ [النحل: 90].\n\nوعن عبد الله بن عمرو رضي الله عنهما أن رسول الله ﷺ قال:\n«ليس منا من لم يرحم صغيرنا، ويعرف شرف كبيرنا». [رواه أبو داود والترمذي، وصححه الألباني].\n\nوعن أبي ذر رضي الله عنه قال: قال رسول الله ﷺ:\n«إخوانكم خولكم جعلهم الله تحت أيديكم، فمن كان أخوه تحت يده فليطعمه مما يأكل، وليلبسه مما يلبس، ولا تكلفوهم ما يغلبهم، فإن كلفتموهم فأعينوهم». [متفق عليه].",
                                "source": "النحل: 90؛ رواه أبو داود والترمذي؛ متفق عليه",
                                "tags": [
                                        "إكرام الكبير",
                                        "رحمة الصغير",
                                        "الإحسان لمن تحت اليد"
                                ],
                                "createdAt": "2026-07-25T00:00:00Z"
                        }
